CREATE TABLE IF NOT EXISTS association_users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_salt TEXT NOT NULL,password_hash TEXT NOT NULL,contact_name TEXT NOT NULL,phone TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,activated_at TEXT,welcome_sent_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS association_memberships (id TEXT PRIMARY KEY,association_user_id TEXT NOT NULL,municipality TEXT NOT NULL,association_slug TEXT NOT NULL,association_name TEXT NOT NULL,stated_role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',reviewed_by TEXT,reviewed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(association_user_id,municipality,association_slug),FOREIGN KEY(association_user_id) REFERENCES association_users(id));
CREATE INDEX IF NOT EXISTS association_memberships_review ON association_memberships(status,created_at);
CREATE TABLE IF NOT EXISTS association_activation_tokens (id TEXT PRIMARY KEY,association_user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,purpose TEXT NOT NULL,expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL,FOREIGN KEY(association_user_id) REFERENCES association_users(id));
CREATE INDEX IF NOT EXISTS association_tokens_user ON association_activation_tokens(association_user_id,purpose,used_at,expires_at);
